from datetime import datetime, timedelta, time
from pathlib import Path

def parse(path):
    evs, cur = [], None
    for line in Path(path).read_text().splitlines():
        line = line.strip()
        if line == 'BEGIN:VEVENT':
            cur = {}
        elif line.startswith('DTSTART:'):
            cur['s'] = datetime.strptime(line.split(':', 1)[1], '%Y%m%dT%H%M%SZ')
        elif line.startswith('DTEND:'):
            cur['e'] = datetime.strptime(line.split(':', 1)[1], '%Y%m%dT%H%M%SZ')
        elif line.startswith('SUMMARY:'):
            cur['n'] = line.split(':', 1)[1]
        elif line == 'END:VEVENT':
            evs.append(cur); cur = None
    return evs

cal = {n: parse('/app/%s_calendar.ics' % n) for n in ('alice', 'bob', 'carol')}

def busy(evs):
    w = []
    for ev in evs:
        w.append((ev['s'], ev['e'], ev['n']))
        # Carol's 15-min buffer: unavailable right after anything ending >= 16:45
        if ev['e'].time() >= time(16, 45):
            w.append((ev['e'], ev['e'] + timedelta(minutes=15), 'buffer after ' + ev['n']))
    return w

wins = {n: busy(e) for n, e in cal.items()}

def ok(s, e):
    if s.weekday() > 4: return False                                        # Mon-Fri
    if not (s.time() >= time(9, 0) and e.time() <= time(14, 0)): return False  # Alice hard
    if s.time() < time(10, 0) or e.time() > time(18, 0): return False         # Bob hard
    if s.weekday() in (1, 3) and e.time() > time(16, 30): return False        # Bob Tue/Thu
    if s.time() < time(9, 0) or e.time() > time(17, 0): return False          # Carol hours
    ls = datetime.combine(s.date(), time(12, 0)); le = datetime.combine(s.date(), time(12, 30))
    if s < le and e > ls: return False                                       # Carol lunch
    for n in wins:
        for bs, be, name in wins[n]:
            if s < be and e > bs: return False
    return True

D = timedelta(minutes=60)
valid = {}
d = datetime(2024, 1, 15)
while d.date() <= datetime(2024, 1, 19).date():
    t = datetime.combine(d.date(), time(9, 0))
    limit = datetime.combine(d.date(), time(18, 0))
    while t + D <= limit:
        if ok(t, t + D):
            valid.setdefault(d.date(), []).append(t)
        t += timedelta(minutes=1)
    d += timedelta(days=1)

for k in sorted(valid):
